#include <vector>
#include <algorithm>
#include <iostream>

int main() {
    std::vector<int> coll = {1, 5, 2, 5, 3, 5, 4};
    int val = 5;

    // 1. std::remove shifts non-5s forward, returns new logical end
    auto new_end = std::remove(coll.begin(), coll.end(), val);

    // coll is now: {1, 2, 3, 4, X, X, X} where X are indeterminate values
    // new_end points to the first 'X'.

    // 2. Erase physically removes the elements and updates size()
    coll.erase(new_end, coll.end());

    // Output: 1 2 3 4
    for (int x : coll) { std::cout << x << " "; }
    std::cout << "\n";
}
